1575	export const pushUndo = (currentState: TextBufferState): TextBufferState => {
1576	  const snapshot: UndoHistoryEntry = {
1577	    lines: [...currentState.lines],
1578	    cursorRow: currentState.cursorRow,
1579	    cursorCol: currentState.cursorCol,
1580	    pastedContent: { ...currentState.pastedContent },
1581	    expandedPaste: currentState.expandedPaste
1582	      ? { ...currentState.expandedPaste }
1583	      : null,
1584	  };
1585	  const newStack = [...currentState.undoStack, snapshot];
1586	  if (newStack.length > historyLimit) {
1587	    newStack.shift();
1588	  }
1589	  return { ...currentState, undoStack: newStack, redoStack: [] };
1590	};
