1592	function generatePastedTextId(
1593	  content: string,
1594	  lineCount: number,
1595	  pastedContent: Record<string, string>,
1596	): string {
1597	  const base =
1598	    lineCount > LARGE_PASTE_LINE_THRESHOLD
1599	      ? `[Pasted Text: ${lineCount} lines]`
1600	      : `[Pasted Text: ${content.length} chars]`;
1601	
1602	  let id = base;
1603	  let suffix = 2;
1604	  while (pastedContent[id]) {
1605	    id = base.replace(']', ` #${suffix}]`);
1606	    suffix++;
1607	  }
1608	  return id;
1609	}
