/**
 * Toggles the case of a single character. Non-alphabetic characters are
 * returned unchanged.
 */
function toggleCharCase(char: string): string {
  const upper = char.toUpperCase();
  if (char !== upper) {
    // Character has an uppercase form that differs -> it was lowercase.
    return upper;
  }
  // Either already uppercase or has no case distinction.
  return char.toLowerCase();
}

/**
 * Finds the column of the count-th occurrence of `char` at or after
 * `startCol`, searching forward. Returns null if not found.
 */
function findCharForwardCol(
  codePoints: string[],
  startCol: number,
  char: string,
  count: number,
): number | null {
  let found = 0;
  for (let i = Math.max(0, startCol); i < codePoints.length; i++) {
    if (codePoints[i] === char) {
      found++;
      if (found >= count) {
        return i;
      }
    }
  }
  return null;
}

