  codePoints: string[],
  startCol: number,
  char: string,
  count: number,
): number | null {
  let found = 0;
  for (let i = Math.min(startCol, codePoints.length - 1); i >= 0; i--) {
    if (codePoints[i] === char) {
      found++;
      if (found >= count) {
        return i;
      }
    }
  }
  return null;
